entries[92724] = { ["name"] = "Schnelles Windross", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört ein schnelles Windross oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Eine von Pandarias meistgesuchten Kreaturen, die ihren Reitern Glück bringen sollen.\"\nWoW-Shop" }
entries[92726] = { ["name"] = "Bipsis Handschuhe", ["text"] = "Wird beim Anlegen gebunden\nHände Stoff\n2 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
