entries[92736] = { ["name"] = "Gen-lis Essenz", ["text"] = "Questgegenstand\n\"Die Bewegungen dieser Staubpartikel sind unberechenbar. Wenn Ihr die Hände bewegt, schweben sie um sie herum.\"" }
