entries[92754] = { ["name"] = "Feuerwein von Ruqin", ["text"] = "Questgegenstand\n\"Die weiße Flüssigkeit verströmt einen strengen, beißenden Geruch. Ein kleiner Schluck breitet sich wie Feuer in Eurem Inneren aus, gefolgt von einem warmen, lebendigen Gefühl im Kopf.\"" }
entries[92756] = { ["name"] = "Wein der Erinnerungen", ["text"] = "Questgegenstand\nBenutzen: Werdet Zeuge einer Vision aus Shan Kiens Vergangenheit. (3 Sek. Abklingzeit)\n\"Der Wein riecht nach einem Dutzend Aromen und Gewürzen, die gleichermaßen widerlich und verführerisch sind...\"" }
entries[92763] = { ["name"] = "Helm der Kor'kron", ["text"] = "Questgegenstand\nBenutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen. (3 Sek. Abklingzeit)\n\"Der polierte Helm ist verbeult.\"" }
entries[92764] = { ["name"] = "Rüstung der Kor'kron", ["text"] = "Questgegenstand\nBenutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen.\n\"Ziemlich schwer.\"" }
entries[92765] = { ["name"] = "Stiefel der Kor'kron", ["text"] = "Questgegenstand\nBenutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen.\n\"Da hat wohl jemand seine Füße nicht gewaschen...\"" }
entries[92766] = { ["name"] = "Kor'kron-Verkleidung", ["text"] = "Questgegenstand\nBenutzen: Verkleidet Euch als ein Mitglied der Kor'kron. (3 Sek. Abklingzeit)" }
