entries[92975] = { ["name"] = "Das rosarote Murmeltier", ["text"] = "Questgegenstand\nEinzigartig\n\"Seine Farbgebung täuscht über seine Stärke hinweg.\"" }
entries[92976] = { ["name"] = "Der rostige Dolch", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieses Getränk wird warm serviert und mutet wie Spülwasser an, aber Ihr solltet seinen Effekt nicht unterschätzen...\"" }
entries[92977] = { ["name"] = "Mogumelonenüberraschung", ["text"] = "Questgegenstand\nEinzigartig\n\"Fragt lieber nicht danach, was die Überraschung ist. Ihr wollt es gar nicht wissen...\"" }
entries[92978] = { ["name"] = "Einladung für Bizmos VIP-Lounge", ["text"] = "Questgegenstand\nEinzigartig\n\"Nur für die Besten. Die Allerbesten!\"" }
entries[92979] = { ["name"] = "Mega-mächtiger Heiltrank", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt 9167 Gesundheit wieder her. Kann nur in einer Kampfarena verwendet werden. (5 Min Abklingzeit)\n\"Wird nur unter der Ladentheke verkauft – Trickser sind beim Publikum nicht gern gesehen.\"\nVerkaufspreis:" }
entries[92980] = { ["name"] = "Freundschaftsdienst", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft eine Freundschaftsbekundung auf einen Grubenkämpfer, die dessen Primärwert leicht erhöht. Bis zu 100-mal stapelbar. (10 Sek. Abklingzeit)\n\"Unterstützt den aktuellen Grubenkämpfer!\"\nVerkaufspreis:" }
entries[93009] = { ["name"] = "Erkennungsmarke eines Soldaten der Operation Schildwall", ["text"] = "Questgegenstand\n\"Der eingeprägte Kopf eines Löwen wurde erst kürzlich mit großer Hingabe blankpoliert.\"" }
entries[93019] = { ["name"] = "Versiegelte Notiz", ["text"] = "Questgegenstand\n\"Diese Notiz ist säuberlich versiegelt und trägt das Siegel von Silbermond.\"\n<Zum Lesen rechtsklicken>" }
entries[93022] = { ["name"] = "Belebbarer Stein", ["text"] = "Questgegenstand\n\"Dieser Stein scheint zu vibrieren, wenn Ihr ihn berührt.\"" }
entries[93025] = { ["name"] = "Kampfmaschine", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick die Kampfmaschine beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Rang 3 in Bizmos Boxbar.\nBenötigt Rang 3 in der Shlae'gararena." }
entries[93026] = { ["name"] = "\"Praktisches \"\"Kratz-Ab\"\"-Spray\"", ["text"] = "Questgegenstand\nBenutzen: Feuert eine Ladung \"Kratz-Ab\" auf aufgebrachte Schieferspinnen.\n\"Funktioniert in 40% aller Fälle – auf alle Fälle! Kontakt mit Augen, Haut und Kleidung unbedingt vermeiden.\"" }
