entries[93168] = { ["name"] = "Großer gepanzerter Greif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren großen gepanzerten Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Operation Schildwall\n- Ehrfürchtig\nVerkaufspreis:\n\"Als Mitglied der Allianz könnte man auf keinen zuverlässigeren Kampfgefährten hoffen als auf diesen noblen Greifen.\"\nVerkäufer:\nAgent Malley\nZone:\nKrasarangwildnis\nFraktion:\nOperation Schildwall - Ehrfürchtig\nKosten:" }
entries[93169] = { ["name"] = "Großer gepanzerter Wyvern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren großen gepanzerten Wyvern oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Herrschaftsoffensive\n- Ehrfürchtig\nVerkaufspreis:\n\"Diese wilde Bestie, die bei Wyvernführern berühmt ist, war eins der ersten Reittiere, das für die Herrschaftsoffensive der Horde ausgewählt wurde.\"\nVerkäufer:\nFangzahnschlächter Gurkna\nZone:\nKrasarangwildnis\nFraktion:\nHerrschaftsoffensive - Ehrfürchtig\nKosten:" }
entries[93179] = { ["name"] = "Altmetall", ["text"] = "Questgegenstand\n\"Ein bisschen verbeult und angesengt, aber noch brauchbar.\"" }
entries[93180] = { ["name"] = "Rekonfigurierte Fernsteuerung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Einfach zielen und drücken! (5 Sek. Abklingzeit)\n\"Überreste eines Warnaufklebers sind erkennbar: Toxisch – Gefährlich!\"" }
entries[93187] = { ["name"] = "Instabiler Sprengstoff", ["text"] = "Questgegenstand\nBenutzen: Werft den Sprengstoff auf die Kisten voll Goblinsprengstoff und LAUFT WEG!\n\"Ruckartige Bewegungen und offene Flammen unbedingt vermeiden!\"" }
entries[93189] = { ["name"] = "Artefakt der Korun", ["text"] = "Questgegenstand\n\"Diese Artefakte beschreiben, wie die Korun die Macht des Sha für sich nutzen konnten.\"" }
entries[93190] = { ["name"] = "Sha-berührte Klaue", ["text"] = "Questgegenstand\n\"Die Hand des Spruchwirkers der Korun ist zu einer monströsen Klaue mutiert. Dunkle Energie geht von ihr aus. Hilda und Brann könnten sich dafür interessieren.\"" }
