entries[93194] = { ["name"] = "Blutverschmierte Schriftrolle", ["text"] = "Einzigartig\n\"Das scheint früher wichtig gewesen zu sein, aber die Zeit hat ihren Tribut gefordert.\"\nVerkaufspreis:" }
