entries[93385] = { ["name"] = "Großer Greif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren großen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die ausgezeichnete Sehkraft der Greifen ermöglicht es ihnen, in die Ferne zu blicken und ihre Reiter vor bevorstehenden Gefahren zu warnen.\"\nQuest:\nDie Stille\nZone:\nKun-Lai-Gipfel" }
entries[93386] = { ["name"] = "Großer Wyvern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren großen Wyvern oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wyvern kommen aus einigen der lebensfeindlichsten Gebiete von Kalimdor, weshalb sie meisterhaft darin sind, sich an eine beliebige Umgebung zu gewöhnen.\"\nQuest:\nAtem der dunkelsten Schatten\nZone:\nKun-Lai-Gipfel" }
