entries[93626] = { ["name"] = "Gestohlenes Geschenk", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Winterhauchfest\n\"Da steht Euer Name drauf!\"\n<Zum Öffnen rechtsklicken>" }
entries[93655] = { ["name"] = "Agentenabzeichen der Kirin Tor", ["text"] = "Wird beim Aufheben gebunden\n\"Von der Rüstung eines toten Agenten der Kirin Tor gerissen. Die Sonnenhäscher bieten eine Belohnung für diese Gegenstände.\"" }
entries[93656] = { ["name"] = "Agentenabzeichen der Sonnenhäscher", ["text"] = "Wird beim Aufheben gebunden\n\"Von der Rüstung eines toten Agenten der Sonnenhäscher gerissen. Die Kirin Tor bieten eine Belohnung für diese Gegenstände.\"" }
entries[93662] = { ["name"] = "Zügel des gepanzerten Himmelskreischers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren gepanzerten Himmelskreischer oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die heldenhaften Seelen, die sich jeder Herausforderung der Mogutyrannen gestellt haben, können sich voller Stolz auf einem kriegsbereiten Himmelskreischer in die Lüfte begeben.\"\nErfolg:\nRuhm des Donnernden Schlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[93666] = { ["name"] = "Ausgeburt von Horridon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare Ausgeburt von Horridon oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn man einen Wirbelsturm kommen sieht, verschwindet man lieber. Horridon würde gegen den Wirbelsturm ankämpfen und dabei siegen.\"\nBeute von:\nHorridon\nZone:\nDer Thron des Donners" }
entries[93668] = { ["name"] = "Saurierfetisch", ["text"] = "Questgegenstand\nBenutzen: Wendet diesen Fetisch auf einen Raptor, Sauriden, Himmelskreischer oder ein Terrorhorn in den Bestienpferchen an, um Kontrolle über sie zu erlangen. Die Ergebnisse sind möglicherweise unvorhersehbar. (10 Sek. Abklingzeit)" }
entries[93669] = { ["name"] = "Windstoßgrimoire", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick ein Windstoßgrimoire beschwören oder wieder freigeben.\n80 ( 80)" }
entries[93671] = { ["name"] = "Schädel des geisterhaften Streitrosses", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört ein geisterhaftes Streitross oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nicht alle Opfer Medivhs sind wirklich endgültig fort.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[93672] = { ["name"] = "Dunkles Portal", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"UND SIEHE, DAS DUNKLE PORTAL. Na ja, zumindest eine kleine Version davon.\"" }
