entries[93724] = { ["name"] = "Dunkelmond-Spielpreis", ["text"] = "Wird beim Aufheben gebunden\n\"Was wohl darin ist?\"\n<Zum Öffnen rechtsklicken>" }
entries[93730] = { ["name"] = "Dunkelmond-Zylinder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Erhöht gewonnene Erfahrung und Ruf 1 Stunde lang um 10%. Der Hut wird dabei verbraucht.\nBenötigt Dunkelmond-Jahrmarkt\nVerkaufspreis:" }
entries[93731] = { ["name"] = "Mogukodexfragment", ["text"] = "Questgegenstand\n\"Enthält einen kleinen Teil des arkanen Kodex, der den Eingang zur Werft der Zandalari blockiert.\"" }
entries[93732] = { ["name"] = "Dunkelmond-Anglermütze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKopf\nBenutzen: Erzeugt Schiffswracktrümmer. Funktioniert nur, während der Dunkelmond-Jahrmarkt geöffnet hat. (1 Stunde Abklingzeit)\nAnlegen: Beim Anlegen: +5 Angelfertigkeit.\nVerkaufspreis:" }
entries[93733] = { ["name"] = "Maske des Geisterrufers", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser sorgfältig geschnitzten Maske wohnt die Macht des Schlangen-Loa inne, den sie darstellt.\"" }
entries[93734] = { ["name"] = "Maske des dunklen Mystikers", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Magie innerhalb der Maske ist launisch. Sie ehrt nur die Starken und trachtet danach, die Schwachen zu zerstören.\"" }
entries[93735] = { ["name"] = "Ritualartefakt", ["text"] = "Questgegenstand\n\"Wer weiß, für welche dunklen magischen Zwecke dieses Artefakt gedacht war...\"" }
entries[93736] = { ["name"] = "Loabeseelte Klinge", ["text"] = "Questgegenstand\n\"Blutflecken sind von den filigranen Verzierungen auf Klinge und Griff dieser Waffe fast nicht zu unterscheiden.\"" }
