entries[93742] = { ["name"] = "Heiltrank", ["text"] = "Szenariogegenstand\nBenutzen: Stellt 25% Eurer maximalen Gesundheit wieder her. (5 Min Abklingzeit)" }
entries[93751] = { ["name"] = "Gesegnete Fackel", ["text"] = "Questgegenstand\nBenutzen: Verbrennt die mumifizierten Überreste eines Mogu. (2 Sek. Abklingzeit)" }
entries[93761] = { ["name"] = "Arkaner Emanzipator", ["text"] = "Questgegenstand\nBenutzen: Befreit einen gefangenen Späher im Umkreis von 15 Metern aus den Zaubern der Mogu und teleportiert ihn in Sicherheit." }
entries[93792] = { ["name"] = "Kopf des königlichen Kämmerers", ["text"] = "Questgegenstand\n\"Dieser Mogukopf verspottet Euch andauernd wegen Eurer erbärmlichen Statur.\"" }
entries[93793] = { ["name"] = "Schulter des königlichen Kämmerers", ["text"] = "Questgegenstand\n\"Eine falsche Bewegung und dieser Stein wird in Euren Händen zu Staub zerfallen.\"" }
entries[93794] = { ["name"] = "Stab des königlichen Kämmerers", ["text"] = "Questgegenstand\n\"Diese steinerne Waffe sieht eher zeremoniell als praktisch aus.\"" }
entries[93795] = { ["name"] = "Haar des königlichen Kämmerers", ["text"] = "Questgegenstand\n\"Viel davon ist nicht mehr übrig.\"" }
entries[93796] = { ["name"] = "Torso des königlichen Kämmerers", ["text"] = "Questgegenstand\n\"Aus irgendeinem Grund ist er viel leichter als er aussieht.\"" }
entries[93803] = { ["name"] = "Zauberformel von Gura", ["text"] = "Questgegenstand\nBenutzen: Ruft eine Kreatur aus dem Totenreich. In der Nähe des letzten Ruheplatzes von Gura dem Zurückgeforderten anwenden. (3 Sek. Abklingzeit)" }
entries[93805] = { ["name"] = "Späherbericht an die Sonnenhäscher", ["text"] = "Questgegenstand\n\"Enthält Details zu den Bewegungen der Kirin Tor und ihrer Truppenstärke auf der ganzen Insel.\"" }
entries[93806] = { ["name"] = "Resonanzsiphon", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kann benutzt werden, um die geschwächte Zandalariseele aus den Überresten des Wächters zu ziehen. (5 Sek. Abklingzeit)" }
entries[93823] = { ["name"] = "Herausforderungskarte: Bruce", ["text"] = "Rang 8\nWird beim Aufheben gebunden\nEinzigartig: Herausforderungskarte (1)\n\"Einem Vertreter der Kampfgilde überreichen, um Bruce herauszufordern. Ihr könnt nur jeweils eine Herausforderungskarte besitzen.\"\nVerkaufspreis:" }
