entries[93896] = { ["name"] = "Kraftvolle Hand der Gerechtigkeit", ["text"] = "Wird an Kriegsmeute gebunden\nSchmuck\nAnlegen: Heilt Euch um 2% Eurer maximalen Gesundheit, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt." }
entries[93897] = { ["name"] = "Durchdringendes Auge der Bestie", ["text"] = "Wird an Kriegsmeute gebunden\nSchmuck\nAnlegen: Stellt 2% Eures maximalen Manas wieder her, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt." }
entries[93898] = { ["name"] = "Hinterlassenes Insigne der Horde", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nSchmuck\nBenötigt eine Horde-Rasse\nBenutzen: Entfernt alle bewegungseinschränkenden Effekte und Kontrollverlusteffekte. (2 Min Abklingzeit)" }
entries[93899] = { ["name"] = "Hinterlassenes Insigne der Allianz", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nSchmuck\nBenötigt eine Allianz-Rasse\nBenutzen: Entfernt alle bewegungseinschränkenden Effekte und Kontrollverlusteffekte. (2 Min Abklingzeit)" }
entries[93900] = { ["name"] = "Geerbtes Mal der Tyrannei", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nSchmuck\nBenutzen: Erhöht die maximale Gesundheit 15 Sek. lang um 0 . Teilt eine Abklingzeit mit anderen Schmuckstücken des Kampfmeisters. (2 Min Abklingzeit)" }
entries[93902] = { ["name"] = "Versengter drakonischer Deflektor", ["text"] = "Wird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung" }
entries[93903] = { ["name"] = "Verwitterter Schild des Beobachters", ["text"] = "Wird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung" }
entries[93904] = { ["name"] = "Staubiger Foliant der Verlorenen", ["text"] = "Wird an Kriegsmeute gebunden\nIn Schildhand geführt" }
entries[93955] = { ["name"] = "Verzierter Fangzahn der Zandalarigeisterbinder", ["text"] = "Wird beim Aufheben gebunden\n\"Eine aufwendig geschnitzte Schlange wickelt sich um einen langen Fangzahn.\"\nVerkaufspreis:" }
entries[93956] = { ["name"] = "Verzierter Stachel der Zandalarigiftmischer", ["text"] = "Wird beim Aufheben gebunden\n\"An diesem gravierten Spinnenstachel befindet sich noch der Giftbeutel, wahrscheinlich für rituelle Vergiftungen.\"\nVerkaufspreis:" }
entries[93957] = { ["name"] = "Verzierter Bestienherrenspeer der Zandalari", ["text"] = "Wird beim Aufheben gebunden\n\"Die ausgestaltete Spitze dieses Speers wurde aus dem Schädel eines Terrorhorns geschnitzt.\"\nVerkaufspreis:" }
entries[93958] = { ["name"] = "Gestohlene Moguurne", ["text"] = "Wird beim Aufheben gebunden\n\"Die Saurok missbrauchen dieses unschätzbar wertvolle, zehntausend Jahre alte Artefakt als Nachttopf.\"\nVerkaufspreis:" }
entries[93959] = { ["name"] = "Juwelenbesetzte Kakerlake der Skumklingen", ["text"] = "Wird beim Aufheben gebunden\n\"Große, grobe Edelsteine sind unbeholfen auf die Flügel dieser noch zappelnden Kakerlake geklebt worden.\"\nVerkaufspreis:" }
entries[93960] = { ["name"] = "Juwelenbesetztes Teufelssaurierei", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses mit endlos vielen kleinen Edelsteinen besetzte Geschenk der Zandalari zeigt das Abbild eines ehemaligen Mogukaisers.\"\nVerkaufspreis:" }
