entries[94228] = { ["name"] = "Zügel des kobaltblauen Urterrorhorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares kobaltblaues Urterrorhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Wenn man anner Seite von Raptoren kämpft, braucht man 'n Reittier, das sie nicht so leicht fress'n.\" - unbekannter Dinomant\nBeute von:\nOondasta\nOrt:\nInsel der Riesen" }
entries[94229] = { ["name"] = "Zügel des schiefergrauen Urterrorhorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares schiefergraues Urterrorhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Masken sollen die Terrorhörner nicht kontrollieren. Es soll nur niemand Euer Gesicht sehen, wenn das Tier sich schließlich gegen Euch richtet.\"\nBeute von:\nKriegshetzer der Zandalari\nZone:\nSchreckensöde, Krasarangwildnis, Kun-Lai-Gipfel, Tonlongsteppe, Tal der Vier Winde" }
entries[94230] = { ["name"] = "Zügel des goldgelben Urterrorhorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares goldgelbes Urterrorhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Es gibt ein altes Zandalarisprichwort über wilde Terrorhörner: \"Lauft!\"\"\nBeute von:\nKriegshetzer der Zandalari\nZone:\nSchreckensöde, Kun-Lai-Gipfel, Tonlongsteppe, Tal der Vier Winde" }
entries[94231] = { ["name"] = "Zügel des jadegrünen Urterrorhorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares jadegrünes Urterrorhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die festlichen Farben lenken von der tödlichen Absicht ab.\"\nBeute von:\nKriegshetzer der Zandalari\nZone:\nSchreckensöde, Kun-Lai-Gipfel, Tonlongsteppe, Tal der Vier Winde" }
entries[94232] = { ["name"] = "Uralter Foliant zur Dinomantie", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenutzen: Erlernt die uralten Zandalarigeheimnisse des Zähmens von Terrorhörnern.\nLernt die uralten Zandalarigeheimnisse der Terrorhornzähmung.\nVerkaufspreis:" }
