entries[94288] = { ["name"] = "Riesiger Dinosaurierknochen", ["text"] = "\"Ein gewaltiger Knochen, der von einer der gewaltigen Bestien auf der Insel der Riesen stammt.\"" }
entries[94289] = { ["name"] = "Spukender Geist", ["text"] = "Handwerksmaterial\n\"Der Geist weigert sich, das Gefilde der Sterblichen zu verlassen und kann sich mit Gegenständen großer Macht verbinden.\"" }
entries[94290] = { ["name"] = "Zügel des knochenweißen Urraptors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren knochenweißen Urraptor und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Mit acht Monaten sind sie tödlich, äußerst tödlich.\" - Hemet Nesingwary Jr.\nQuest:\nEin Berg riesiger Dinosaurierknochen\nZone:\nInsel der Riesen" }
entries[94291] = { ["name"] = "Zügel des roten Urraptors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren roten Urraptor und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Raptoren haben sich in praktisch allen Landen von Azeroth verbreitet. Es ist unklar, ob die Trolle sie hergeführt haben oder sie ihnen gefolgt sind.\"\nBeute von:\nZerbrochene Ureischale" }
entries[94292] = { ["name"] = "Zügel des schwarzen Urraptors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Urraptor und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Geschwindigkeit, Gerissenheit und Wildheit sind Dinge, die Trolle und Raptoren aneinander bewundern.\"\nBeute von:\nZerbrochene Ureischale" }
entries[94293] = { ["name"] = "Zügel des grünen Urraptors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren grünen Urraptor und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Raptoren sind genauso treu, wie sie bösartig sind. Wenn Ihr kein Freund seid, seid Ihr eine Mahlzeit.\" - Kijara\nBeute von:\nZerbrochene Ureischale" }
entries[94295] = { ["name"] = "Urei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 3 tagen (Realzeit)\n\"Aus diesem Ei schlüpft etwas.\"\nVerkaufspreis:" }
entries[94296] = { ["name"] = "Zerbrochene Ureischale", ["text"] = "Wird beim Aufheben gebunden\n\"Aus diesem Ei ist etwas geschlüpft!\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
